#define WL_V1_DATA_VECTOR(name_, envelope_, integrity_, flags_, wire_)         \
  {name_, envelope_, integrity_, WL_PACKET_DATA, flags_, 0x1234U,             \
   UINT64_C(0x0102030405060708), UINT32_C(0x0A0B0C0D), wl_v1_payload,          \
   sizeof(wl_v1_payload), wire_, sizeof(wire_)}
#define WL_V1_ACK_VECTOR(name_, envelope_, wire_)                              \
  {name_, envelope_, WL_INTEGRITY_CRC32C, WL_PACKET_ACK, 0U, 0U,              \
   UINT64_C(0x0102030405060708), UINT32_C(0x0A0B0C0D), NULL, 0U, wire_,        \
   sizeof(wire_)}

